/**
 * Founding-terms document + canonical JSON + docHash, byte-for-byte with C1.
 *
 * Source of truth: docs/CONTRACTS.md v0 @ 30d1ef6 ("Canonical agreement hash and
 * signatures", CR-C2-005 / D-014 / D-023) and C1's implementation at
 * agent/identity@1b502e6 `src/modules/agreements/{canonical,terms}.ts`.
 * `c1-vectors.json` was generated by running C1's own code; `terms.test.ts`
 * asserts this module reproduces every byte and hash.
 *
 * The UI uses this ONLY to preview the hash while founders edit. The hash that is
 * signed always comes from C1's server-built EIP-712 payload, never from here.
 *
 * Rules match C1 @ a00016b exactly, including the sparse-array fix and container-depth
 * counting (root container = level 1, more than 16 rejected). `terms.test.ts` runs both the
 * vectors generated from C1's code and C1's official tests/identity/vectors/canonical-v1.json.
 */
import { getAddress, isAddress, keccak256, stringToHex } from "viem";
import type { Address, Hex, VentureId } from "../types";

export const AGREEMENT_SCHEMA = "vestige.founding-terms/1" as const;
export const LEGAL_DISCLAIMER =
  "Workspace agreement between founders. Not a legal incorporation, not legal advice, and not an equity or token issuance.";
const MAX_DEPTH = 16;

export class CanonicalError extends Error {}

/** vestige restricted canonical JSON (CONTRACTS v0). Throws CanonicalError. */
export function canonicalize(value: unknown, depth = 0): string {
  if (value === null) return "null";
  switch (typeof value) {
    case "string":
      return JSON.stringify(value.normalize("NFC"));
    case "boolean":
      return value ? "true" : "false";
    case "number":
      if (!Number.isSafeInteger(value)) throw new CanonicalError("Agreement numbers must be whole numbers (use basis points).");
      return Object.is(value, -0) ? "0" : String(value);
    case "object": {
      if (depth + 1 > MAX_DEPTH) throw new CanonicalError("Agreement is nested too deeply.");
      if (Array.isArray(value)) {
        if (Object.getPrototypeOf(value) !== Array.prototype) throw new CanonicalError("Agreement must be plain JSON.");
        const parts: string[] = [];
        for (let i = 0; i < value.length; i++) {
          if (!(i in value) || value[i] === undefined) throw new CanonicalError("Agreement arrays must not be sparse or contain undefined.");
          parts.push(canonicalize(value[i], depth + 1));
        }
        return `[${parts.join(",")}]`;
      }
      const proto = Object.getPrototypeOf(value);
      if (proto !== Object.prototype && proto !== null) throw new CanonicalError("Agreement must be plain JSON.");
      if (Object.getOwnPropertySymbols(value).length > 0) throw new CanonicalError("Agreement must be plain JSON.");
      const entries = Object.entries(value as Record<string, unknown>)
        .filter(([, v]) => v !== undefined)
        .map(([k, v]) => [k.normalize("NFC"), v] as const);
      if (new Set(entries.map(([k]) => k)).size !== entries.length) throw new CanonicalError("Duplicate keys after normalisation.");
      // Default string comparison = UTF-16 code units, as CONTRACTS requires.
      entries.sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
      return `{${entries.map(([k, v]) => `${JSON.stringify(k)}:${canonicalize(v, depth + 1)}`).join(",")}}`;
    }
    default:
      throw new CanonicalError("Agreement contains a non-JSON value.");
  }
}

export function docHashOf(canonicalJson: string): Hex {
  return keccak256(stringToHex(canonicalJson));
}

export type FounderTerms = {
  wallet: Address;
  role: string;
  contribution: string;
  /** basis points; all founders sum to 10000 */
  ownershipBps: number;
  vestingIntent: string;
};

/** Exactly C1's validated document — the thing that is hashed. */
export type FoundingTermsDoc = {
  schema: typeof AGREEMENT_SCHEMA;
  ventureId: VentureId;
  effectiveDate: string;
  decisionRule: string;
  founders: FounderTerms[];
  notes: string;
  disclaimer: string;
};

/** Body of POST /api/agreements/ventures/:id/versions (C1 validates and rebuilds). */
export type FoundingTermsInput = {
  effectiveDate: string;
  decisionRule: string;
  founders: { wallet: Address; role: string; contribution: string; ownershipBps: number; vestingIntent: string }[];
  notes?: string;
};

export type TermsProblem = { field: string; message: string };

const textOk = (v: unknown, max: number): v is string => typeof v === "string" && v.trim().length > 0 && v.length <= max;

/**
 * Mirrors C1 `buildTermsDoc` (same limits, trimming, lowercase wallets, sort by
 * wallet, fixed disclaimer). Returns problems instead of throwing so the form can
 * show them inline. C1 remains the validator of record.
 */
export function buildTermsDoc(
  ventureId: VentureId,
  verifiedFounders: Address[],
  input: FoundingTermsInput,
): { ok: true; doc: FoundingTermsDoc } | { ok: false; problems: TermsProblem[] } {
  const problems: TermsProblem[] = [];
  const need = (field: string, v: unknown, max: number, label: string) => {
    if (!textOk(v, max)) problems.push({ field, message: `${label} is required (max ${max} characters).` });
  };
  need("effectiveDate", input.effectiveDate, 10, "Effective date");
  const effectiveDate = (input.effectiveDate ?? "").trim();
  if (textOk(input.effectiveDate, 10) && (!/^\d{4}-\d{2}-\d{2}$/.test(effectiveDate) || Number.isNaN(Date.parse(`${effectiveDate}T00:00:00Z`))))
    problems.push({ field: "effectiveDate", message: "Effective date must be YYYY-MM-DD." });
  need("decisionRule", input.decisionRule, 500, "Decision rule");

  const verified = verifiedFounders.map((w) => w.toLowerCase());
  if (input.founders.length !== verified.length) problems.push({ field: "founders", message: "Terms must cover exactly the venture's verified founders." });
  const founders: FounderTerms[] = [];
  input.founders.forEach((f, i) => {
    const p = `founders.${i}`;
    if (!isAddress(f.wallet, { strict: false })) problems.push({ field: `${p}.wallet`, message: "Invalid wallet address." });
    if (!Number.isInteger(f.ownershipBps) || f.ownershipBps < 0 || f.ownershipBps > 10_000)
      problems.push({ field: `${p}.ownershipBps`, message: "Ownership must be a whole number of basis points, 0–10000." });
    need(`${p}.role`, f.role, 120, "Role");
    need(`${p}.contribution`, f.contribution, 1000, "Contribution");
    need(`${p}.vestingIntent`, f.vestingIntent, 500, "Vesting intent");
    if (isAddress(f.wallet, { strict: false }))
      founders.push({
        wallet: getAddress(f.wallet).toLowerCase() as Address,
        role: (f.role ?? "").trim(),
        contribution: (f.contribution ?? "").trim(),
        ownershipBps: f.ownershipBps,
        vestingIntent: (f.vestingIntent ?? "").trim(),
      });
  });
  const wallets = new Set(founders.map((f) => f.wallet));
  if (wallets.size !== founders.length || verified.some((w) => !wallets.has(w as Address)))
    problems.push({ field: "founders", message: "Terms must name each verified founder exactly once." });
  const total = input.founders.reduce((a, f) => a + (Number.isFinite(f.ownershipBps) ? f.ownershipBps : 0), 0);
  if (total !== 10_000) problems.push({ field: "ownership", message: `Proposed ownership must total 100% (10000 bps). Now ${total}.` });
  if (problems.length) return { ok: false, problems };

  founders.sort((a, b) => (a.wallet < b.wallet ? -1 : 1));
  return {
    ok: true,
    doc: {
      schema: AGREEMENT_SCHEMA,
      ventureId,
      effectiveDate,
      decisionRule: input.decisionRule.trim(),
      founders,
      notes: typeof input.notes === "string" ? input.notes.slice(0, 2000) : "",
      disclaimer: LEGAL_DISCLAIMER,
    },
  };
}

/** Preview the docHash C1 will compute for this input, or the problems blocking it. */
export function previewTerms(ventureId: VentureId, verifiedFounders: Address[], input: FoundingTermsInput) {
  const built = buildTermsDoc(ventureId, verifiedFounders, input);
  if (!built.ok) return { ok: false as const, problems: built.problems };
  const json = canonicalize(built.doc);
  return { ok: true as const, doc: built.doc, json, hash: docHashOf(json) };
}

/** Parse the founders-only canonicalJson returned by C1 back into the document. */
export function parseTermsDoc(canonicalJson?: string): FoundingTermsDoc | null {
  if (!canonicalJson) return null;
  try {
    const d = JSON.parse(canonicalJson) as FoundingTermsDoc;
    return d && d.schema === AGREEMENT_SCHEMA && Array.isArray(d.founders) ? d : null;
  } catch {
    return null;
  }
}

/** EIP-712 domain/type — CONTRACTS v0; identical to C1 `FOUNDING_TERMS_DOMAIN/TYPES`. */
export const FOUNDING_TERMS_DOMAIN = { name: "vestige", version: "1", chainId: 11155111 } as const;
export const FOUNDING_TERMS_TYPES = {
  FoundingTerms: [
    { name: "ventureId", type: "bytes32" },
    { name: "agreementId", type: "bytes32" },
    { name: "version", type: "uint256" },
    { name: "docHash", type: "bytes32" },
    { name: "nonce", type: "uint256" },
    { name: "expiry", type: "uint256" },
  ],
} as const;

export const bpsToPercent = (bps: number) => `${(bps / 100).toFixed(bps % 100 === 0 ? 0 : 2)}%`;
